/*
 * Per-axis JOG feed-rate controls (task: "in the JOG panel, between the dial
 * and the spindle speed settings, add per-axis speed controls for XY, Z, A,
 * B and C; pick from a preset list whose variants are generated by the same
 * algorithm as the spindle presets, with one of the options being to edit the
 * speed").
 *
 * Layout and behavior notes:
 * - The row lives in the JOG panel body between the dial layout and the
 *   spindle section; axis groups appear only when the machine configuration
 *   reports those axes (A-C columns show when A/B/C exist).
 * - Preset values follow the spindle algorithm: `min`, four evenly spaced
 *   values rounded to a sensible step, and `max` — deduplicated and sorted.
 * - The last option is "edit": it opens a small popup with a numeric input so
 *   an arbitrary feed rate can be applied (exactly like the spindle's custom
 *   speed control).
 * - Speeds are persisted to local storage through jog-speed-dialog.js helpers
 *   and pushed to `POST /api/jog/speed`, where the controller stores them per
 *   axis group (XY shared, Z own, A/B/C own feeds).
 */

import { t } from "./i18n.js";
import { isValidJogSpeed, saveJogSpeeds, sendJogSpeeds } from "./jog-speed-dialog.js";

/** Axis groups rendered by this control row, in display order. */
const AXIS_GROUPS = [
  { key: "xy", axes: ["X", "Y"], labelKey: "jog.axisSpeed.xy", fallback: "XY" },
  { key: "z", axes: ["Z"], labelKey: "jog.axisSpeed.z", fallback: "Z" },
  { key: "a", axes: ["A"], labelKey: "jog.axisSpeed.a", fallback: "A" },
  { key: "b", axes: ["B"], labelKey: "jog.axisSpeed.b", fallback: "B" },
  { key: "c", axes: ["C"], labelKey: "jog.axisSpeed.c", fallback: "C" },
];

/** Fallback feed limit when the machine configuration does not report one. */
const DEFAULT_MAX_FEED = 5000;
/** Smallest feed a group may be set to; keeps presets away from zero. */
const MIN_FEED_FLOOR = 10;

/**
 * Rounds a feed value to a readable step, mirroring the spindle preset
 * rounding (100 up to 9000, else 1000): for feeds the same rule reads well
 * because machine feeds usually span hundreds to thousands mm/min.
 *
 * @param {number} maximum - Largest feed of the group (mm/min or deg/min).
 * @returns {number} Rounding granularity used when spacing presets.
 */
function feedRounding(maximum) {
  return maximum <= 9000 ? 100 : 1000;
}

/**
 * Generates the preset list for one axis group by the spindle algorithm:
 * `min`, four evenly spaced rounded values and `max`, deduplicated, sorted.
 *
 * @param {number} minimum - Smallest allowed feed of the group.
 * @param {number} maximum - Largest allowed feed of the group.
 * @returns {number[]} Ascending unique preset values.
 */
export function feedPresets(minimum, maximum) {
  const low = Math.max(MIN_FEED_FLOOR, Math.min(minimum, maximum));
  const high = Math.max(low, maximum);
  const rounding = feedRounding(high);
  const values = [low];
  for (let index = 1; index <= 4; index += 1) {
    const evenlySpaced = low + ((high - low) * index) / 5;
    values.push(Math.round(evenlySpaced / rounding) * rounding);
  }
  values.push(high);
  return [
    ...new Set(values.map((value) => Math.min(high, Math.max(low, value)))),
  ].sort((left, right) => left - right);
}

/**
 * Derives [min, max] feed limits for one axis group from the machine
 * configuration: the minimum configured max_velocity of the group's axes is
 * the ceiling, and a tenth of it (floored at MIN_FEED_FLOOR) is the preset
 * base, so slow setups keep the presets meaningful.
 *
 * @param {object|null} configuration - `status.configuration` payload.
 * @param {string[]} axes - Axis letters belonging to the group.
 * @returns {[number, number]} Ordered [min, max] pair.
 */
function groupLimits(configuration, axes) {
  const entries = Array.isArray(configuration?.axes) ? configuration.axes : [];
  const velocities = axes
    .map((letter) =>
      entries.find((entry) => String(entry.axis).toUpperCase() === letter),
    )
    .map((entry) => Number(entry?.max_velocity))
    .filter((value) => Number.isFinite(value) && value > 0);
  const maximum = velocities.length ? Math.min(...velocities) : DEFAULT_MAX_FEED;
  const minimum = Math.max(MIN_FEED_FLOOR, Math.round(maximum / 10));
  return [minimum, maximum];
}

/**
 * Creates the per-axis speed control row.
 *
 * @param {object} options - Dependencies.
 * @param {HTMLElement} options.container - Element that hosts the row
 *   (`#jog-axis-speeds`).
 * @param {() => object} options.getSpeeds - Returns the live speed settings
 *   object from the shared JOG context.
 * @param {(speeds: object) => void} options.onSpeeds - Called after a speed is
 *   applied so the context stores and persists the new values.
 * @returns {{render: Function, refresh: Function}} render(configuration)
 *   rebuilds the visible groups; refresh() re-localizes and re-labels.
 */
export function initJogAxisSpeeds({ container, getSpeeds, onSpeeds }) {
  // Currently open editor popup (only one at a time), or null.
  let openPopup = null;

  /**
   * Removes the open popup from the DOM, if any.
   *
   * @returns {void}
   */
  function closePopup() {
    openPopup?.remove();
    openPopup = null;
    container
      .querySelectorAll("[aria-expanded='true']")
      .forEach((button) => button.setAttribute("aria-expanded", "false"));
  }

  /**
   * Applies one speed to a group: validates, sends to the server, notifies
   * the caller and repaints the button labels.
   *
   * @param {string} key - Speed group key (`xy`, `z`, `a`, `b`, `c`).
   * @param {number} value - Feed rate in group units per minute.
   * @param {HTMLElement} button - Trigger button, used for error reporting.
   * @returns {Promise<void>} Resolves when the server accepted the value.
   */
  async function applySpeed(key, value, button) {
    if (!isValidJogSpeed(value)) {
      button.title = t("jog.axisSpeed.invalid", { max: 100000 });
      return;
    }
    const speeds = { ...getSpeeds(), [key]: value };
    // Rotary trio stays in sync only when the whole group was edited through
    // the legacy "rotary" key; individual a/b/c edits change one axis only.
    try {
      await sendJogSpeeds({ [key]: value });
    } catch (error) {
      button.title = t("common.errorPrefix", { message: error.message });
      return;
    }
    onSpeeds(speeds);
    saveJogSpeeds(speeds);
    refresh();
  }

  /**
   * Builds one group control: caption + preset button with the dropdown.
   *
   * @param {object} group - Entry of AXIS_GROUPS.
   * @param {[number, number]} limits - [min, max] feed limits.
   * @returns {HTMLElement} The group element.
   */
  function buildGroup(group, limits) {
    const [minimum, maximum] = limits;
    const wrapper = document.createElement("div");
    wrapper.className = "jog-axis-speed";
    wrapper.dataset.speedGroup = group.key;

    const label = document.createElement("span");
    label.className = "jog-axis-speed-label";
    label.textContent = t(group.labelKey);
    label.setAttribute("data-i18n-group", group.key);

    const button = document.createElement("button");
    button.type = "button";
    button.className = "jog-axis-speed-button";
    button.setAttribute("aria-haspopup", "menu");
    button.setAttribute("aria-expanded", "false");

    /**
     * Opens the preset menu for this group (positioned absolutely inside the
     * wrapper so the panel layout never shifts).
     *
     * @returns {void}
     */
    function openMenu() {
      closePopup();
      const menu = document.createElement("div");
      menu.className = "jog-axis-speed-menu";
      menu.setAttribute("role", "menu");

      for (const preset of feedPresets(minimum, maximum)) {
        const item = document.createElement("button");
        item.type = "button";
        item.setAttribute("role", "menuitem");
        item.textContent = String(preset);
        item.title = t("jog.axisSpeed.presetTitle", {
          speed: preset,
          max: maximum,
        });
        item.addEventListener("click", async () => {
          closePopup();
          await applySpeed(group.key, preset, button);
        });
        menu.append(item);
      }

      // Last entry: edit an arbitrary value, like the spindle custom speed.
      const edit = document.createElement("div");
      edit.className = "jog-axis-speed-edit";
      const input = document.createElement("input");
      input.type = "number";
      input.min = String(MIN_FEED_FLOOR);
      input.max = String(100000);
      input.step = "any";
      input.value = String(getSpeeds()[group.key] ?? minimum);
      input.setAttribute(
        "aria-label",
        t("jog.axisSpeed.editAria", { group: group.fallback }),
      );
      const apply = document.createElement("button");
      apply.type = "button";
      // `common.apply` is a static dictionary key already used by every
      // Apply button in the UI.
      apply.textContent = t("common.apply");
      apply.addEventListener("click", async () => {
        closePopup();
        await applySpeed(group.key, Number(input.value), button);
      });
      edit.append(input, apply);
      menu.append(edit);

      wrapper.appendChild(menu);
      openPopup = menu;
      button.setAttribute("aria-expanded", "true");
    }

    button.addEventListener("click", (event) => {
      event.stopPropagation();
      if (openPopup && wrapper.contains(openPopup)) {
        closePopup();
      } else {
        openMenu();
      }
    });

    wrapper.append(label, button);
    return wrapper;
  }

  /**
   * (Re)labels every visible group button with its current speed and refreshes
   * tooltips. Called after each apply and on locale changes.
   *
   * @returns {void}
   */
  function refresh() {
    const speeds = getSpeeds();
    container.querySelectorAll(".jog-axis-speed").forEach((wrapper) => {
      const key = wrapper.dataset.speedGroup;
      const group = AXIS_GROUPS.find((entry) => entry.key === key);
      if (!group) return;
      const button = wrapper.querySelector(".jog-axis-speed-button");
      button.textContent = String(Math.round(Number(speeds[key]) || 0));
      const caption = wrapper.querySelector(".jog-axis-speed-label");
      caption.textContent = t(group.labelKey);
      button.title = t("jog.axisSpeed.title", {
        group: group.fallback,
        speed: button.textContent,
      });
      button.setAttribute(
        "aria-label",
        t("jog.axisSpeed.aria", { group: group.fallback }),
      );
    });
  }

  /**
   * Rebuilds the row for one machine configuration: XY and Z are always
   * present; A/B/C groups appear only when the axes exist.
   *
   * @param {object|null} configuration - `status.configuration` payload.
   * @returns {void}
   */
  function render(configuration) {
    closePopup();
    container.textContent = "";
    for (const group of AXIS_GROUPS) {
      const present = group.axes.every((letter) =>
        (Array.isArray(configuration?.axes) ? configuration.axes : [])
          .map((entry) => String(entry.axis).toUpperCase())
          .includes(letter),
      );
      // XY/Z groups never hide: the minimum machine has X/Y/Z, and keeping
      // their controls stable avoids layout jitter during reconnection.
      if (!present && group.key !== "xy" && group.key !== "z") continue;
      container.append(buildGroup(group, groupLimits(configuration, group.axes)));
    }
    refresh();
  }

  // Any click outside the container closes an open menu.
  document.addEventListener("pointerdown", (event) => {
    if (openPopup && !container.contains(event.target)) closePopup();
  });

  return { render, refresh };
}
